/**
 * apps/index.ts — Atlas application registration.
 *
 * This is the only file in the shell permitted to:
 *   - import from 03_Application source (via named Vite aliases)
 *   - call registerApp()
 *
 * Imported by main.tsx as a side-effect before the React tree mounts.
 * AppRegistry is fully populated before the first render.
 *
 * To add a new native app:
 *   1. Add alias to vite.config.ts resolve.alias
 *   2. Add matching paths entry to tsconfig.json
 *   3. Add registerApp() call below
 *
 * To add a new external app:
 *   1. Add VITE_<APP>_URL to .env and .env.production
 *   2. Add registerApp() call below using import.meta.env.VITE_<APP>_URL
 */

import React from "react";
import { registerApp } from "../registry/AppRegistry";
import type { NativeAppNavConfig, ExternalAppNavConfig } from "../types/nav";

// ── WorkoutTracker (native) ───────────────────────────────────────────────────
// @workout resolves to 03_Application/WorkoutTracker/src via vite.config.ts alias.
// ShellEntry.tsx must be a default-export component rendering nested Routes.

const WorkoutApp = React.lazy(() => import("@workout/ShellEntry"));

const _workoutConfig: NativeAppNavConfig = {
  appId: "workout",
  label: "Workout",
  basePath: "/workout",
  order: 1,
  kind: "native",
  component: WorkoutApp,
  mobilePrimaryNav: [
    { id: "log",         label: "Log",         path: "/workout",             order: 1 },
    { id: "performance", label: "Performance", path: "/workout/performance", order: 2 },
  ],
  desktopNav: [
    { id: "log",         label: "Log",         path: "/workout",             order: 1 },
    { id: "performance", label: "Performance", path: "/workout/performance", order: 2 },
    { id: "history",     label: "History",     path: "/workout/history",     order: 3 },
  ],
  secondaryMenu: [
    { id: "settings", label: "Settings", path: "/workout/settings", order: 1 },
  ],
};

registerApp(_workoutConfig);

// ── TaskTracker (external) ────────────────────────────────────────────────────
// href sourced from VITE_TASKS_URL. If the variable is absent or empty,
// registerApp() will skip this entry (MISSING_EXTERNAL_HREF); TaskTracker
// will not appear in GlobalNav or Launcher.

const _tasksConfig: ExternalAppNavConfig = {
  appId: "tasks",
  label: "Tasks",
  order: 2,
  kind: "external",
  // Empty string fallback keeps TypeScript happy; registerApp() rejects it.
  href: import.meta.env.VITE_TASKS_URL ?? "",
};

registerApp(_tasksConfig);

