/**
 * GlobalNav.tsx — Level-1 navigation bar.
 *
 * Renders the Atlas launcher NavLink first, then all registered app entries
 * sorted by AppNavConfig.order. Native apps use react-router-dom NavLink;
 * external apps use a plain <a> with target='_blank'. External entries only
 * appear when their href was valid at registration time (VITE_TASKS_URL set).
 */

import { useContext } from "react";
import { NavLink } from "react-router-dom";
import { ShellContext } from "../context/ShellContext";
import type { AppNavConfig } from "../types/nav";

export function GlobalNav() {
  const ctx = useContext(ShellContext);
  if (!ctx) return null;

  const { registry } = ctx;

  // Sort all entries by AppNavConfig.order ascending.
  const sorted: AppNavConfig[] = Array.from(registry.values()).sort(
    (a, b) => a.order - b.order
  );

  return (
    <nav className="shell-global-nav" aria-label="Global navigation">
      {/* Atlas launcher — always first, always a NavLink to '/' */}
      <NavLink
        to="/"
        end
        className={({ isActive }) =>
          "shell-nav-item shell-nav-launcher" + (isActive ? " active" : "")
        }
      >
        Atlas
      </NavLink>

      {/* Registered app entries */}
      {sorted.map((app) => {
        if (app.kind === "native") {
          return (
            <NavLink
              key={app.appId}
              to={app.basePath}
              className={({ isActive }) =>
                "shell-nav-item" + (isActive ? " active" : "")
              }
            >
              {app.label}
            </NavLink>
          );
        }

        // kind === 'external' — plain anchor, no active state
        return (
          <a
            key={app.appId}
            href={app.href}
            target="_blank"
            rel="noopener noreferrer"
            className="shell-nav-item shell-nav-external"
          >
            {app.label}
            {/* External-link indicator */}
            <span className="shell-nav-external-icon" aria-hidden="true">
              ↗
            </span>
          </a>
        );
      })}
    </nav>
  );
}

