/**
 * Launcher.tsx — Atlas launcher view rendered at route '/'.
 *
 * Lists all registered applications sorted by AppNavConfig.order.
 * Native apps use react-router-dom NavLink to their basePath.
 * External apps use a plain <a> with target='_blank'.
 * External apps are only present when their href was valid at registration.
 */

import { useContext } from "react";
import { NavLink } from "react-router-dom";
import { ShellContext } from "../context/ShellContext";
import type { AppNavConfig } from "../types/nav";

export function Launcher() {
  const ctx = useContext(ShellContext);
  if (!ctx) return null;

  const { registry } = ctx;

  const sorted: AppNavConfig[] = Array.from(registry.values()).sort(
    (a, b) => a.order - b.order
  );

  return (
    <div className="shell-launcher">
      <h1 className="shell-launcher-title type-headline">Atlas</h1>

      <ul className="shell-launcher-list" role="list">
        {sorted.map((app) => {
          if (app.kind === "native") {
            return (
              <li key={app.appId} className="shell-launcher-item">
                <NavLink
                  to={app.basePath}
                  className="shell-launcher-link"
                >
                  {app.label}
                </NavLink>
              </li>
            );
          }

          // kind === 'external'
          return (
            <li key={app.appId} className="shell-launcher-item">
              <a
                href={app.href}
                target="_blank"
                rel="noopener noreferrer"
                className="shell-launcher-link shell-launcher-link-external"
              >
                {app.label}
                <span className="shell-launcher-external-icon" aria-hidden="true">
                  ↗
                </span>
              </a>
            </li>
          );
        })}

        {sorted.length === 0 && (
          <li className="shell-launcher-empty type-body">
            No applications registered.
          </li>
        )}
      </ul>
    </div>
  );
}

