/**
 * LocalNav.tsx — Level-2 navigation for the active native application.
 *
 * Returns null when:
 *   - activeAppId is null (launcher state)
 *   - the active config is kind='external'
 *   - no config is found for the active appId
 *
 * On desktop/tablet: renders desktopNav sorted by NavItem.order.
 * On mobile: renders mobilePrimaryNav sorted by NavItem.order.
 * All entries are rendered as react-router-dom NavLinks.
 */

import { useContext } from "react";
import { NavLink } from "react-router-dom";
import { ShellContext } from "../context/ShellContext";
import { getApp } from "../registry/AppRegistry";
import type { NavItem } from "../types/nav";

export function LocalNav() {
  const ctx = useContext(ShellContext);
  if (!ctx) return null;

  const { activeAppId, layoutVariant } = ctx;

  if (activeAppId === null) return null;

  const config = getApp(activeAppId);
  if (!config || config.kind === "external") return null;

  // Select the appropriate nav list based on layout variant, sorted by order.
  const items: NavItem[] =
    layoutVariant === "mobile"
      ? [...config.mobilePrimaryNav].sort((a, b) => a.order - b.order)
      : [...config.desktopNav].sort((a, b) => a.order - b.order);

  if (items.length === 0) return null;

  return (
    <nav className="shell-local-nav" aria-label="Application navigation">
      {items.map((item) => (
        <NavLink
          key={item.id}
          to={item.path}
          end={item.path === config.basePath}
          className={({ isActive }) =>
            "shell-local-nav-item" + (isActive ? " active" : "")
          }
        >
          {item.label}
        </NavLink>
      ))}
    </nav>
  );
}

