/**
 * MoreMenu.tsx — Secondary / "More" menu for the active native application.
 *
 * Returns null when:
 *   - activeAppId is null
 *   - the active config is kind='external'
 *   - secondaryMenu is absent or empty
 *
 * Manages its own open/closed state. Renders a toggle button and a positioned
 * list of NavLinks when open.
 */

import { useState, useContext, useEffect, useRef } from "react";
import { NavLink } from "react-router-dom";
import { ShellContext } from "../context/ShellContext";
import { getApp } from "../registry/AppRegistry";

export function MoreMenu() {
  const ctx = useContext(ShellContext);
  const [open, setOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Close the menu when clicking outside.
  useEffect(() => {
    if (!open) return;
    function handleOutside(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", handleOutside);
    return () => document.removeEventListener("mousedown", handleOutside);
  }, [open]);

  if (!ctx) return null;

  const { activeAppId } = ctx;
  if (activeAppId === null) return null;

  const config = getApp(activeAppId);
  if (!config || config.kind === "external") return null;

  const secondary = config.secondaryMenu;
  if (!secondary || secondary.length === 0) return null;

  const sorted = [...secondary].sort((a, b) => a.order - b.order);

  return (
    <div ref={menuRef} className="shell-more-menu">
      <button
        className="shell-more-menu-toggle"
        aria-label="More options"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
      >
        <span className="shell-more-menu-label">More</span>
        <span aria-hidden="true" className="shell-more-menu-icon">
          {open ? "▲" : "▼"}
        </span>
      </button>

      {open && (
        <div className="shell-more-menu-panel" role="menu">
          {sorted.map((item) => (
            <NavLink
              key={item.id}
              to={item.path}
              role="menuitem"
              className={({ isActive }) =>
                "shell-more-menu-item" + (isActive ? " active" : "")
              }
              onClick={() => setOpen(false)}
            >
              {item.label}
            </NavLink>
          ))}
        </div>
      )}
    </div>
  );
}

