/**
 * ShellErrorBoundary.tsx — React class error boundary for native app outlets.
 *
 * Wraps each native app's Suspense block. Catches render errors and
 * React.lazy load failures. Shell navigation remains functional when active.
 *
 * ErrorCard expects an ApiError shape; the caught Error is adapted to that
 * shape using "client-render-error" as the request_id sentinel value.
 */

import { Component } from "react";
import type { ReactNode, ErrorInfo } from "react";
import ErrorCard from "@platform-ui/components/ErrorCard";
import type { ApiError } from "@platform-ui/api/types";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * Adapts a caught JavaScript Error to the ApiError envelope that ErrorCard expects.
 * Uses "client-render-error" as the request_id sentinel value to distinguish
 * client-side render failures from API-originated errors.
 */
function adaptError(error: Error): ApiError {
  return {
    error: {
      code: "CLIENT_RENDER_ERROR",
      message: error.message || "An unexpected error occurred while rendering this application.",
      detail: error.stack,
      request_id: "client-render-error",
    },
  };
}

export class ShellErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ShellErrorBoundary] Caught render error:", error, info.componentStack);
  }

  render(): ReactNode {
    if (this.state.hasError && this.state.error) {
      return <ErrorCard error={adaptError(this.state.error)} />;
    }
    return this.props.children;
  }
}

