/**
 * ShellLayout.tsx — Root shell component.
 *
 * Mounted once by main.tsx inside BrowserRouter. Owns:
 *   - ShellContext provision (activeAppId, layoutVariant, navigate, registry)
 *   - Responsive layout variant detection via matchMedia
 *   - The top-level Routes tree (native apps only; no Route for external apps)
 *   - GlobalNav, LocalNav, and MoreMenu composition
 *
 * Native app Routes use the '/*' wildcard so sub-paths pass through to the
 * app's own nested Routes in ShellEntry.tsx.
 *
 * activeAppId derivation:
 *   We cannot call useMatch in a loop (Rules of Hooks). Instead, we use
 *   useLocation() and derive the active appId by checking each native
 *   basePath as a prefix against the current pathname. This is safe because
 *   the registry is populated before mount and never mutates at runtime.
 */

import { Suspense, useState, useEffect, useMemo } from "react";
import { Routes, Route, useNavigate, useLocation } from "react-router-dom";
import Skeleton from "@platform-ui/components/Skeleton";
import { ShellContext } from "../context/ShellContext";
import { getRegistry } from "../registry/AppRegistry";
import { GlobalNav } from "./GlobalNav";
import { LocalNav } from "./LocalNav";
import { MoreMenu } from "./MoreMenu";
import { Launcher } from "./Launcher";
import { ShellErrorBoundary } from "./ShellErrorBoundary";
import type { LayoutVariant, NativeAppNavConfig } from "../types/nav";

// ── useLayoutVariant ──────────────────────────────────────────────────────────

/**
 * Private hook. Derives the current layout variant from viewport width.
 *   < 600px    → 'mobile'
 *   600–1024px → 'tablet'
 *   > 1024px   → 'desktop'
 *
 * Updates on viewport change via matchMedia 'change' event.
 */
function useLayoutVariant(): LayoutVariant {
  function derive(): LayoutVariant {
    if (typeof window === "undefined") return "desktop";
    if (window.matchMedia("(max-width: 599px)").matches) return "mobile";
    if (window.matchMedia("(max-width: 1024px)").matches) return "tablet";
    return "desktop";
  }

  const [variant, setVariant] = useState<LayoutVariant>(derive);

  useEffect(() => {
    const mobileQuery = window.matchMedia("(max-width: 599px)");
    const tabletQuery = window.matchMedia("(max-width: 1024px)");

    function handleChange() {
      setVariant(derive());
    }

    mobileQuery.addEventListener("change", handleChange);
    tabletQuery.addEventListener("change", handleChange);

    return () => {
      mobileQuery.removeEventListener("change", handleChange);
      tabletQuery.removeEventListener("change", handleChange);
    };
  }, []);

  return variant;
}

// ── useActiveAppId ────────────────────────────────────────────────────────────

/**
 * Private hook. Derives the activeAppId from the current URL pathname.
 *
 * Returns the appId of the first native config whose basePath is a prefix
 * of the current pathname, or null if the pathname is '/' or no match.
 *
 * We use useLocation (one hook call, rule-safe) and do prefix matching.
 * basePath matching: pathname must equal basePath exactly OR begin with
 * basePath + '/' to avoid false matches (e.g. /workout-old matching /workout).
 */
function useActiveAppId(nativeConfigs: NativeAppNavConfig[]): string | null {
  const { pathname } = useLocation();

  if (pathname === "/") return null;

  for (const cfg of nativeConfigs) {
    const base = cfg.basePath;
    if (pathname === base || pathname.startsWith(base + "/")) {
      return cfg.appId;
    }
  }

  return null;
}

// ── ShellLayout ───────────────────────────────────────────────────────────────

export function ShellLayout() {
  const navigate = useNavigate();
  const layoutVariant = useLayoutVariant();

  // Read the registry once — fully populated before this component mounts.
  const registry = useMemo(() => getRegistry(), []);

  // Collect all native configs for route rendering and activeAppId resolution.
  const nativeConfigs: NativeAppNavConfig[] = useMemo(
    () =>
      Array.from(registry.values()).filter(
        (c): c is NativeAppNavConfig => c.kind === "native"
      ),
    [registry]
  );

  // Derive activeAppId from URL; null at launcher state or unknown routes.
  const activeAppId = useActiveAppId(nativeConfigs);

  // Determine whether LocalNav and MoreMenu should render.
  const activeConfig = activeAppId ? registry.get(activeAppId) : undefined;
  const showLocalNav = activeConfig?.kind === "native";

  return (
    <ShellContext.Provider
      value={{
        activeAppId,
        layoutVariant,
        navigate,
        registry,
      }}
    >
      <div
        className={`shell-layout shell-layout--${layoutVariant}`}
        data-active-app={activeAppId ?? "none"}
      >
        {/* Level-1 navigation — always rendered */}
        <GlobalNav />

        {/* Level-2 navigation — only for active native app */}
        {showLocalNav && <LocalNav />}

        {/* More / secondary menu — only for active native app */}
        {showLocalNav && <MoreMenu />}

        {/* Content area — top-level Routes */}
        <main className="shell-content">
          <Routes>
            {/* Launcher at root */}
            <Route path="/" element={<Launcher />} />

            {/* One Route per native app; '/*' passes sub-paths to the app's Routes */}
            {nativeConfigs.map((cfg) => (
              <Route
                key={cfg.appId}
                path={cfg.basePath + "/*"}
                element={
                  <Suspense fallback={<Skeleton />}>
                    <ShellErrorBoundary>
                      <cfg.component />
                    </ShellErrorBoundary>
                  </Suspense>
                }
              />
            ))}

            {/* Unknown routes fall through to Launcher (UNKNOWN_ROUTE failure mode) */}
            <Route path="*" element={<Launcher />} />
          </Routes>
        </main>
      </div>
    </ShellContext.Provider>
  );
}

