/**
 * ShellContext.ts — React context for shell navigation state.
 *
 * Provided by ShellLayout. Consumed by GlobalNav, LocalNav, MoreMenu,
 * Launcher, and (indirectly, via useShellNav) by native application components.
 */

import { createContext } from "react";
import type { NavigateFunction } from "react-router-dom";
import type { AppNavConfig, LayoutVariant } from "../types/nav";

/**
 * The value shape provided by ShellLayout's context.
 *
 * activeAppId is null when the current URL matches no registered native
 * app basePath (i.e. the shell is showing the Launcher at '/').
 */
export interface ShellContextValue {
  /** appId of the currently active native application, or null at launcher state. */
  activeAppId: string | null;
  /** Current responsive layout variant derived from viewport width. */
  layoutVariant: LayoutVariant;
  /** react-router-dom navigate function from the enclosing BrowserRouter. */
  navigate: NavigateFunction;
  /** Read-only snapshot of the full app registry as populated at startup. */
  registry: ReadonlyMap<string, AppNavConfig>;
}

/**
 * React context for shell state. Default value is undefined; ShellLayout
 * always provides a real value. useShellNav asserts it is not undefined.
 */
export const ShellContext = createContext<ShellContextValue | undefined>(undefined);

