/**
 * useShellNav.ts — Public hook for native application components.
 *
 * Provides access to the active app identity and the shell-level navigate
 * function. Must be called inside the ShellLayout tree.
 */

import { useContext } from "react";
import type { NavigateFunction } from "react-router-dom";
import { ShellContext } from "../context/ShellContext";

export interface UseShellNavResult {
  /** appId of the currently active native application, or null at launcher state. */
  activeAppId: string | null;
  /** react-router-dom navigate function from the shell's BrowserRouter. */
  navigate: NavigateFunction;
}

/**
 * Hook for native application components to read activeAppId and navigate.
 *
 * Throws a descriptive error if called outside the ShellLayout tree
 * (i.e. when ShellContext has not been provided).
 */
export function useShellNav(): UseShellNavResult {
  const ctx = useContext(ShellContext);
  if (ctx === undefined) {
    throw new Error("useShellNav must be called inside ShellLayout");
  }
  return {
    activeAppId: ctx.activeAppId,
    navigate: ctx.navigate,
  };
}

