/**
 * main.tsx — Shell Vite entry point.
 *
 * Import order is intentional:
 *   1. apps/index.ts — populates AppRegistry as a side-effect before mount.
 *   2. @platform-ui/index.css — platform primitive CSS (design tokens, component styles).
 *   3. ./shell.css — shell layout styles (overrides and additions on top of platform CSS).
 *
 * Renders: StrictMode > BrowserRouter > ShellLayout into #root.
 * BrowserRouter is owned here; no application component may instantiate another one.
 */

import "./apps/index";
import "@platform-ui/index.css";
import "./shell.css";

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { ShellLayout } from "./components/ShellLayout";

const rootElement = document.getElementById("root");
if (!rootElement) {
  throw new Error("[Atlas Shell] No #root element found in the document.");
}

createRoot(rootElement).render(
  <StrictMode>
    <BrowserRouter>
      <ShellLayout />
    </BrowserRouter>
  </StrictMode>
);

