/**
 * AppRegistry.ts — Module-level application registration store.
 *
 * Called exclusively from src/apps/index.ts before the React tree mounts.
 * Shell components read the registry via getRegistry() and getApp().
 * _registry is not exported; all access goes through the public functions.
 */

import type { AppNavConfig } from "../types/nav";

// ── Private store ─────────────────────────────────────────────────────────────

const _registry = new Map<string, AppNavConfig>();

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Validates and registers an AppNavConfig.
 *
 * Validation rules by kind:
 *   native  — component must be truthy; basePath must be non-empty;
 *             mobilePrimaryNav and desktopNav must be present arrays.
 *             mobilePrimaryNav is capped at 5 items: truncated + console.warn in dev.
 *   external — href must be a non-empty string.
 *              Empty string is the same failure as missing href.
 *
 * On any validation failure: console.error + skip; no throw.
 * Duplicate appId: console.warn + overwrite (last write wins).
 */
export function registerApp(config: AppNavConfig): void {
  const { appId } = config;

  if (!appId || typeof appId !== "string") {
    console.error("[AppRegistry] registerApp: appId is missing or invalid — skipping.");
    return;
  }

  if (config.kind === "native") {
    if (!config.component) {
      console.error(
        `[AppRegistry] registerApp: native config '${appId}' missing component — skipping.`
      );
      return;
    }
    if (!config.basePath || typeof config.basePath !== "string" || config.basePath.trim() === "") {
      console.error(
        `[AppRegistry] registerApp: native config '${appId}' missing or empty basePath — skipping.`
      );
      return;
    }
    if (!Array.isArray(config.mobilePrimaryNav)) {
      console.error(
        `[AppRegistry] registerApp: native config '${appId}' mobilePrimaryNav is absent — skipping.`
      );
      return;
    }
    if (!Array.isArray(config.desktopNav)) {
      console.error(
        `[AppRegistry] registerApp: native config '${appId}' desktopNav is absent — skipping.`
      );
      return;
    }

    // Enforce 5-item mobilePrimaryNav cap (Material Design constraint).
    let validated = config;
    if (config.mobilePrimaryNav.length > 5) {
      if (import.meta.env.DEV) {
        console.warn(
          `[AppRegistry] registerApp: native config '${appId}' mobilePrimaryNav has ` +
            `${config.mobilePrimaryNav.length} items (max 5); truncating to 5.`
        );
      }
      validated = {
        ...config,
        mobilePrimaryNav: config.mobilePrimaryNav.slice(0, 5),
      };
    }

    if (_registry.has(appId)) {
      console.warn(
        `[AppRegistry] registerApp: duplicate appId '${appId}' — overwriting existing entry.`
      );
    }
    _registry.set(appId, validated);
    return;
  }

  if (config.kind === "external") {
    if (!config.href || typeof config.href !== "string" || config.href.trim() === "") {
      console.error(
        `[AppRegistry] registerApp: external config '${appId}' has absent or empty href ` +
          `(MISSING_EXTERNAL_HREF) — skipping.`
      );
      return;
    }

    if (_registry.has(appId)) {
      console.warn(
        `[AppRegistry] registerApp: duplicate appId '${appId}' — overwriting existing entry.`
      );
    }
    _registry.set(appId, config);
    return;
  }

  // Unreachable with well-typed callers, but guard against runtime misuse.
  console.error(
    `[AppRegistry] registerApp: unknown kind on config '${appId}' — skipping.`
  );
}

/**
 * Returns a read-only snapshot of all registered app configs.
 * Called once by ShellLayout to populate ShellContext.
 */
export function getRegistry(): ReadonlyMap<string, AppNavConfig> {
  return _registry;
}

/**
 * Returns the AppNavConfig for the given appId, or undefined if not registered.
 * Used by LocalNav and MoreMenu to look up the active app's config.
 */
export function getApp(appId: string | null | undefined): AppNavConfig | undefined {
  if (!appId) return undefined;
  return _registry.get(appId);
}

