/*
 * shell.css — Atlas Shell layout styles.
 *
 * Uses tokens from @platform-ui/index.css (already imported before this file
 * in main.tsx). No application-specific styles permitted here.
 *
 * Design language reference: 00_Blueprint/UI/02_UI_DesignLanguage
 *   §5  Desktop sidebar
 *   §8  Tablet collapsible sidebar
 *   §14 Mobile bottom navigation (Material Design, max 5 items)
 *
 * Detailed visual treatment (active states, icons, typography refinements)
 * is assigned to UI_Implementer per component_architecture.json deferrals.
 */

/* ── Shell constants ──────────────────────────────────────────────────────── */

:root {
  --shell-sidebar-width:       240px;
  --shell-nav-item-height:     48px;
  --shell-bottom-nav-height:   64px;
  --shell-local-nav-width:     200px;
}

/* ── Base layout — desktop sidebar ───────────────────────────────────────── */

.shell-layout {
  display: flex;
  flex-direction: row;
  min-height: 100vh;
  background: var(--md-sys-color-background);
}

/* Desktop: fixed-width left column + flex-grow content */
.shell-layout--desktop .shell-global-nav,
.shell-layout--tablet  .shell-global-nav {
  width: var(--shell-sidebar-width);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--md-sys-color-surface);
  border-right: 1px solid var(--md-sys-color-outline-variant);
  padding: var(--space-md) 0;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}

/* Mobile: global nav becomes a bottom bar */
.shell-layout--mobile {
  flex-direction: column;
}

.shell-layout--mobile .shell-global-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: var(--shell-bottom-nav-height);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-around;
  background: var(--md-sys-color-surface);
  border-top: 1px solid var(--md-sys-color-outline-variant);
  z-index: 100;
  padding: 0 var(--space-sm);
}

/* ── Global nav items ─────────────────────────────────────────────────────── */

.shell-nav-item {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 0 var(--space-md);
  height: var(--shell-nav-item-height);
  text-decoration: none;
  color: var(--md-sys-color-on-surface-variant);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.1px;
  border-radius: 0 24px 24px 0;
  transition: background var(--motion-state), color var(--motion-state);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shell-layout--desktop .shell-nav-item:hover,
.shell-layout--tablet  .shell-nav-item:hover {
  background: var(--md-sys-color-surface-variant);
  color: var(--md-sys-color-on-surface);
}

.shell-layout--desktop .shell-nav-item.active,
.shell-layout--tablet  .shell-nav-item.active {
  background: var(--md-sys-color-primary-container);
  color: var(--md-sys-color-on-primary-container);
}

/* Mobile bottom nav items */
.shell-layout--mobile .shell-nav-item {
  flex: 1;
  flex-direction: column;
  justify-content: center;
  height: var(--shell-bottom-nav-height);
  padding: 0;
  border-radius: 0;
  font-size: 12px;
  text-align: center;
}

.shell-layout--mobile .shell-nav-item.active {
  color: var(--md-sys-color-primary);
}

/* Launcher entry — slightly larger to distinguish from app entries */
.shell-nav-launcher {
  font-weight: 700;
  font-size: 16px;
  color: var(--md-sys-color-primary);
  margin-bottom: var(--space-sm);
}

/* External link indicator icon */
.shell-nav-external-icon {
  font-size: 11px;
  opacity: 0.6;
  margin-left: 2px;
}

/* ── Local nav (level-2, sidebar only) ───────────────────────────────────── */

.shell-local-nav {
  display: flex;
  flex-direction: column;
  width: var(--shell-local-nav-width);
  flex-shrink: 0;
  padding: var(--space-md) 0;
  background: var(--md-sys-color-background);
  border-right: 1px solid var(--md-sys-color-outline-variant);
}

.shell-layout--mobile .shell-local-nav {
  /* On mobile, LocalNav items are handled differently (via MoreMenu or inline). */
  display: none;
}

.shell-local-nav-item {
  display: flex;
  align-items: center;
  padding: 0 var(--space-md);
  height: var(--shell-nav-item-height);
  text-decoration: none;
  color: var(--md-sys-color-on-surface-variant);
  font-size: 14px;
  font-weight: 400;
  border-radius: 0 24px 24px 0;
  transition: background var(--motion-state), color var(--motion-state);
}

.shell-local-nav-item:hover {
  background: var(--md-sys-color-surface-variant);
  color: var(--md-sys-color-on-surface);
}

.shell-local-nav-item.active {
  background: var(--md-sys-color-secondary-container);
  color: var(--md-sys-color-on-surface);
  font-weight: 500;
}

/* ── More menu ───────────────────────────────────────────────────────────── */

.shell-more-menu {
  position: relative;
}

.shell-more-menu-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 0 var(--space-md);
  height: var(--shell-nav-item-height);
  width: 100%;
  border: none;
  background: transparent;
  color: var(--md-sys-color-on-surface-variant);
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  border-radius: 0 24px 24px 0;
  transition: background var(--motion-state);
  text-align: left;
}

.shell-more-menu-toggle:hover {
  background: var(--md-sys-color-surface-variant);
}

.shell-more-menu-icon {
  font-size: 10px;
  margin-left: auto;
}

.shell-more-menu-panel {
  position: absolute;
  top: 0;
  left: calc(100% + var(--space-xs));
  min-width: 180px;
  background: var(--md-sys-color-surface);
  border: 1px solid var(--md-sys-color-outline-variant);
  border-radius: var(--radius-card);
  box-shadow: var(--elevation-2);
  padding: var(--space-sm) 0;
  z-index: 200;
}

.shell-more-menu-item {
  display: flex;
  align-items: center;
  padding: 0 var(--space-md);
  height: var(--shell-nav-item-height);
  text-decoration: none;
  color: var(--md-sys-color-on-surface);
  font-size: 14px;
  transition: background var(--motion-state);
}

.shell-more-menu-item:hover {
  background: var(--md-sys-color-surface-variant);
}

.shell-more-menu-item.active {
  color: var(--md-sys-color-primary);
  font-weight: 500;
}

/* ── Content area ────────────────────────────────────────────────────────── */

.shell-content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
}

/* On mobile, leave room for the fixed bottom nav bar. */
.shell-layout--mobile .shell-content {
  padding-bottom: var(--shell-bottom-nav-height);
}

/* ── Launcher view ───────────────────────────────────────────────────────── */

.shell-launcher {
  padding: var(--space-xl) var(--space-lg);
  max-width: 480px;
}

.shell-launcher-title {
  margin-bottom: var(--space-lg);
  color: var(--md-sys-color-on-surface);
}

.shell-launcher-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.shell-launcher-item {
  display: block;
}

.shell-launcher-link {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md);
  border-radius: var(--radius-card);
  text-decoration: none;
  color: var(--md-sys-color-on-surface);
  font-size: 16px;
  font-weight: 500;
  background: var(--md-sys-color-surface);
  box-shadow: var(--elevation-1);
  transition: background var(--motion-state), box-shadow var(--motion-state);
}

.shell-launcher-link:hover {
  background: var(--md-sys-color-primary-container);
  box-shadow: var(--elevation-2);
}

.shell-launcher-link-external {
  color: var(--md-sys-color-on-surface-variant);
}

.shell-launcher-external-icon {
  font-size: 12px;
  opacity: 0.6;
  margin-left: auto;
}

.shell-launcher-empty {
  color: var(--md-sys-color-on-surface-variant);
  padding: var(--space-md) 0;
}

/* ── Tablet sidebar — collapsible (basic state; hamburger toggle is UI_Implementer) ── */

.shell-layout--tablet .shell-global-nav {
  width: var(--shell-sidebar-width);
}

