/**
 * nav.ts — Authoritative navigation registration contract types.
 *
 * Import from this file everywhere a nav config is declared or consumed.
 * Never redefine these types locally.
 */

import type { ComponentType, LazyExoticComponent } from "react";

/**
 * A single navigation entry used in mobilePrimaryNav, desktopNav, and secondaryMenu.
 */
export interface NavItem {
  /** Stable identifier for this entry within the app's nav list. */
  id: string;
  /** Human-readable label rendered in nav UI. */
  label: string;
  /** Absolute path passed to react-router-dom NavLink. */
  path: string;
  /**
   * Authoritative sort key. Lower numbers appear first.
   * Floating-point values are permitted to allow insertion without renumbering.
   */
  order: number;
}

/**
 * Registration contract for applications loaded inside the shell outlet.
 * The component must render nested <Routes> without a BrowserRouter.
 */
export interface NativeAppNavConfig {
  /** Stable application identifier. Used as the registry key. */
  appId: string;
  /** Human-readable application name rendered in GlobalNav and Launcher. */
  label: string;
  /**
   * Base URL path for this application. The shell mounts a Route at
   * `basePath + '/*'` so sub-paths pass through to the app's own Routes.
   */
  basePath: string;
  /**
   * Sort key for GlobalNav and Launcher ordering. Authoritative.
   * Registration order is never relied upon.
   */
  order: number;
  kind: "native";
  /**
   * React.lazy component reference. Must be a default-export React component
   * that renders nested Routes without instantiating a BrowserRouter.
   */
  component: LazyExoticComponent<ComponentType>;
  /**
   * Navigation entries shown in mobile bottom navigation.
   * Maximum 5 items enforced at registration (Material Design constraint).
   */
  mobilePrimaryNav: NavItem[];
  /**
   * Navigation entries shown in desktop/tablet sidebar LocalNav.
   * No hard limit.
   */
  desktopNav: NavItem[];
  /**
   * Optional entries rendered in MoreMenu.
   * Absent or empty array means MoreMenu returns null for this app.
   */
  secondaryMenu?: NavItem[];
}

/**
 * Registration contract for applications surfaced as external links.
 * No Route is created. No LocalNav or MoreMenu is rendered.
 */
export interface ExternalAppNavConfig {
  /** Stable application identifier. Used as the registry key. */
  appId: string;
  /** Human-readable application name rendered in GlobalNav and Launcher. */
  label: string;
  /**
   * Sort key for GlobalNav and Launcher ordering. Authoritative.
   * Registration order is never relied upon.
   */
  order: number;
  kind: "external";
  /**
   * Full URL for the external application.
   * Must be a non-empty string. An absent or empty value causes this entry
   * to be rejected at registration (INVALID_NAV_CONFIG / MISSING_EXTERNAL_HREF).
   * Source: import.meta.env.VITE_<APP>_URL — never a hardcoded string.
   */
  href: string;
}

/**
 * Union of both nav config kinds. Used wherever a config is accepted generically.
 */
export type AppNavConfig = NativeAppNavConfig | ExternalAppNavConfig;

/**
 * Responsive layout variant derived from viewport width.
 * Placed in ShellContext and consumed by LocalNav and MoreMenu.
 */
export type LayoutVariant = "desktop" | "tablet" | "mobile";

