/**
 * AppRegistry.test.ts — Unit tests for AppRegistry.
 *
 * Tests are isolated via beforeEach reset using the module-private registry.
 * Because the registry is a module-level Map, we use vi.resetModules() and
 * dynamic re-import to get a fresh registry per test.
 */

import { describe, it, expect, vi, beforeEach } from "vitest";
import type { NativeAppNavConfig, ExternalAppNavConfig } from "../src/types/nav";
import type { ComponentType, LazyExoticComponent } from "react";

// ── Helpers ───────────────────────────────────────────────────────────────────

function makeLazy(): LazyExoticComponent<ComponentType> {
  // Minimal stand-in for React.lazy; only the reference identity matters here.
  return { $$typeof: Symbol.for("react.lazy"), _payload: null, _init: () => null } as unknown as LazyExoticComponent<ComponentType>;
}

function nativeConfig(overrides: Partial<NativeAppNavConfig> = {}): NativeAppNavConfig {
  return {
    appId: "test-app",
    label: "Test App",
    basePath: "/test",
    order: 1,
    kind: "native",
    component: makeLazy(),
    mobilePrimaryNav: [
      { id: "home", label: "Home", path: "/test", order: 1 },
    ],
    desktopNav: [
      { id: "home", label: "Home", path: "/test", order: 1 },
    ],
    ...overrides,
  };
}

function externalConfig(overrides: Partial<ExternalAppNavConfig> = {}): ExternalAppNavConfig {
  return {
    appId: "ext-app",
    label: "External App",
    order: 2,
    kind: "external",
    href: "https://example.com",
    ...overrides,
  };
}

// ── Dynamic import to get fresh registry per test ─────────────────────────────

async function freshRegistry() {
  vi.resetModules();
  const mod = await import("../src/registry/AppRegistry");
  return mod;
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("AppRegistry", () => {
  beforeEach(() => {
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "warn").mockImplementation(() => {});
  });

  it("registers a valid NativeAppNavConfig and retrieves it via getRegistry/getApp", async () => {
    const { registerApp, getRegistry, getApp } = await freshRegistry();
    const config = nativeConfig();
    registerApp(config);
    expect(getRegistry().get("test-app")).toEqual(config);
    expect(getApp("test-app")).toEqual(config);
  });

  it("registers a valid ExternalAppNavConfig with non-empty href", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    const config = externalConfig();
    registerApp(config);
    expect(getRegistry().get("ext-app")).toEqual(config);
  });

  it("skips native config with missing component and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(nativeConfig({ component: undefined as unknown as LazyExoticComponent<ComponentType> }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("skips native config with empty basePath and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(nativeConfig({ basePath: "" }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("skips native config with missing mobilePrimaryNav and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(nativeConfig({ mobilePrimaryNav: undefined as unknown as [] }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("skips native config with missing desktopNav and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(nativeConfig({ desktopNav: undefined as unknown as [] }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("skips external config with missing href and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(externalConfig({ href: undefined as unknown as string }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("skips external config with empty string href (MISSING_EXTERNAL_HREF) and logs console.error", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(externalConfig({ href: "" }));
    expect(getRegistry().size).toBe(0);
    expect(console.error).toHaveBeenCalled();
  });

  it("truncates mobilePrimaryNav to 5 items and logs console.warn in dev", async () => {
    // Vitest sets import.meta.env.DEV = true by default.
    const { registerApp, getApp } = await freshRegistry();
    const sixItems = [1, 2, 3, 4, 5, 6].map((i) => ({
      id: `item-${i}`,
      label: `Item ${i}`,
      path: `/test/${i}`,
      order: i,
    }));
    registerApp(nativeConfig({ mobilePrimaryNav: sixItems }));
    const stored = getApp("test-app") as NativeAppNavConfig;
    expect(stored.mobilePrimaryNav).toHaveLength(5);
    expect(console.warn).toHaveBeenCalled();
  });

  it("does not truncate mobilePrimaryNav with exactly 5 items", async () => {
    const { registerApp, getApp } = await freshRegistry();
    const fiveItems = [1, 2, 3, 4, 5].map((i) => ({
      id: `item-${i}`,
      label: `Item ${i}`,
      path: `/test/${i}`,
      order: i,
    }));
    registerApp(nativeConfig({ mobilePrimaryNav: fiveItems }));
    const stored = getApp("test-app") as NativeAppNavConfig;
    expect(stored.mobilePrimaryNav).toHaveLength(5);
    expect(console.warn).not.toHaveBeenCalled();
  });

  it("overwrites duplicate appId and logs console.warn", async () => {
    const { registerApp, getApp } = await freshRegistry();
    const first = nativeConfig({ label: "First" });
    const second = nativeConfig({ label: "Second" });
    registerApp(first);
    registerApp(second);
    expect((getApp("test-app") as NativeAppNavConfig).label).toBe("Second");
    expect(console.warn).toHaveBeenCalled();
  });

  it("getApp returns undefined for an unregistered appId", async () => {
    const { getApp } = await freshRegistry();
    expect(getApp("not-registered")).toBeUndefined();
  });

  it("getApp returns undefined for null input", async () => {
    const { getApp } = await freshRegistry();
    expect(getApp(null)).toBeUndefined();
  });

  it("getRegistry returns a ReadonlyMap with all registered entries", async () => {
    const { registerApp, getRegistry } = await freshRegistry();
    registerApp(nativeConfig({ appId: "a", basePath: "/a", order: 1 }));
    registerApp(externalConfig({ appId: "b", href: "https://b.com", order: 2 }));
    const reg = getRegistry();
    expect(reg.size).toBe(2);
    expect(reg.has("a")).toBe(true);
    expect(reg.has("b")).toBe(true);
  });
});

