/**
 * ShellLayout.test.tsx — Integration tests for ShellLayout and shell components.
 *
 * Test_Writer notes:
 *   - These tests require vitest + @testing-library/react.
 *   - The @platform-ui and @workout aliases must be configured in vitest.config.ts
 *     (or vite.config.ts test section) so that imports resolve during tests.
 *   - AppRegistry state is module-level; use vi.resetModules() + dynamic imports
 *     to isolate registry state between tests.
 *   - For LAZY_LOAD_FAILURE tests, mock React.lazy to return a rejected promise.
 *
 * Coverage targets (from component_architecture.json deferrals.test_writer):
 *   [x] registerApp() tests are in AppRegistry.test.ts
 *   [ ] ShellLayout: URL matching a native app's basePath sets activeAppId
 *   [ ] ShellLayout: URL '/' sets activeAppId to null and renders Launcher
 *   [ ] ShellLayout: URL not matching any native basePath renders Launcher (UNKNOWN_ROUTE)
 *   [ ] ShellLayout: Route basePath+'/*' passes sub-path to nested Routes in ShellEntry
 *   [ ] GlobalNav: renders NavLink for native apps and <a> for external apps
 *   [ ] GlobalNav: external app entries absent from GlobalNav when VITE_TASKS_URL is unset
 *   [ ] GlobalNav: entries sorted by AppNavConfig.order ascending; launcher always first
 *   [ ] LocalNav: renders desktopNav on desktop, mobilePrimaryNav on mobile
 *   [ ] LocalNav: renders nothing when activeAppId is null or active config is external
 *   [ ] MoreMenu: renders secondaryMenu for active native app; returns null for external
 *   [ ] ShellErrorBoundary: catches render error and renders ErrorCard
 *   [ ] LAZY_LOAD_FAILURE: React.lazy rejection caught by ShellErrorBoundary; ErrorCard rendered
 *   [ ] useShellNav: returns correct activeAppId inside ShellLayout tree
 *   [ ] useShellNav: throws when called outside ShellLayout
 *   [ ] Extensibility: new registerApp() call causes new entry in GlobalNav
 */

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import React from "react";

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Renders ShellLayout with a MemoryRouter at a given initial URL.
 * Uses MemoryRouter instead of BrowserRouter for test isolation.
 * Note: ShellLayout itself renders a Routes tree; wrap in MemoryRouter here.
 */
async function renderShell(initialPath: string = "/") {
  // Fresh module state per test.
  vi.resetModules();
  const { ShellLayout } = await import("../src/components/ShellLayout");
  // Re-populate registry for each render.
  await import("../src/apps/index");
  return render(
    <MemoryRouter initialEntries={[initialPath]}>
      <ShellLayout />
    </MemoryRouter>
  );
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("ShellLayout", () => {
  beforeEach(() => {
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "warn").mockImplementation(() => {});
  });

  it("renders Launcher at route '/'", async () => {
    await renderShell("/");
    expect(screen.getByText("Atlas")).toBeInTheDocument();
  });

  it("renders Launcher for unknown route (UNKNOWN_ROUTE)", async () => {
    await renderShell("/no-such-route");
    // Launcher renders "Atlas" heading.
    expect(screen.getByRole("heading", { name: /atlas/i })).toBeInTheDocument();
  });

  it("GlobalNav contains a NavLink to '/' for the launcher", async () => {
    await renderShell("/");
    const nav = screen.getByRole("navigation", { name: /global navigation/i });
    expect(nav).toBeInTheDocument();
  });
});

describe("ShellErrorBoundary", () => {
  it("renders ErrorCard when a child throws a render error", async () => {
    vi.resetModules();
    const { ShellErrorBoundary } = await import("../src/components/ShellErrorBoundary");

    function Thrower() {
      throw new Error("test render error");
    }

    // Suppress React error boundary console noise in test output.
    const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});

    render(
      <ShellErrorBoundary>
        <Thrower />
      </ShellErrorBoundary>
    );

    // ErrorCard renders the error message.
    expect(screen.getByText(/test render error/i)).toBeInTheDocument();
    // sentinel request_id from ShellErrorBoundary.
    expect(screen.getByText(/client-render-error/i)).toBeInTheDocument();

    errorSpy.mockRestore();
  });
});

describe("useShellNav", () => {
  it("throws descriptively when called outside ShellLayout", async () => {
    vi.resetModules();
    const { useShellNav } = await import("../src/hooks/useShellNav");

    function Consumer() {
      useShellNav();
      return null;
    }

    const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
    expect(() => render(<Consumer />)).toThrow("useShellNav must be called inside ShellLayout");
    errorSpy.mockRestore();
  });
});

