{
  "component_name": "atlas_shell",
  "layer": "02_Platform",
  "source_definition": "00_Definition/definition.md",
  "status": "design_complete",
  "summary": "Provides the shared React UI framework — global layout, two-level navigation, and application registration contract — consumed by all Atlas applications.",

  "classification": {
    "why_platform": "The shell is a reusable technical capability (navigation host, layout engine, routing surface) that carries no domain knowledge. It renders structure declared by applications; it does not interpret meaning from that structure.",
    "non_goals": [
      "domain logic of any kind",
      "business rules",
      "data access or API calls (except navigation config consumption)",
      "application-specific UI logic",
      "settings content (owned by each application)",
      "internal application route guards",
      "page content rendering beyond slot injection"
    ]
  },

  "resolved_decisions": [
    {
      "question": "Does 02_Atlas_Shell replace 02_Platform/UI as the authoritative shell?",
      "decision": "02_Atlas_Shell fully supersedes 02_Platform/UI. The old App.tsx, main.tsx, and pages/ tree are deleted. The platform primitives (react/src/components/, react/src/api/, react/src/hooks/, react/src/index.css) survive and continue to be consumed by the shell and applications. The outer 02_Platform/UI/ Vite host files (non-react/ tree) are removed as they are superseded by the shell's own Vite host.",
      "affects": ["migration_steps in deferrals", "dependencies.internal_required"]
    },
    {
      "question": "Is atlas_shell a standalone Vite app or a publishable npm package?",
      "decision": "Standalone Vite app. The shell is a single Vite HTML host. Applications are co-located source modules loaded into the shell via React.lazy. registerApp() is called at shell startup inside src/apps/index.ts, not inside individual application entry points.",
      "affects": ["internal_flow", "interfaces", "dependencies", "scaffold structure"]
    },
    {
      "question": "Which router?",
      "decision": "react-router-dom v6, history-based (BrowserRouter). The shell owns the top-level BrowserRouter in main.tsx and the top-level Routes in ShellLayout. Each native app gets a nested Route at its declared basePath. Applications use useNavigate and useParams from react-router-dom v6 directly.",
      "affects": ["dependencies.external_required", "internal_flow"]
    },
    {
      "question": "How does src/apps/index.ts import application source from 03_Application?",
      "decision": "Vite path aliases. Each application gets a named alias in vite.config.ts resolve.alias pointing to its source root (e.g. '@workout' -> '../../../03_Application/WorkoutTracker/src'). src/apps/index.ts uses these aliases in React.lazy(() => import('@workout/ShellEntry')) calls. The same aliases are declared in tsconfig.json paths for type checking.",
      "affects": ["vite.config.ts scaffold", "src/apps/index.ts scaffold", "dependencies.forbidden"]
    },
    {
      "question": "Which apps migrate into the shell outlet vs remain external links?",
      "decision": "WorkoutTracker is the pilot native app: its component is lazy-loaded into the shell outlet. All other current apps (TaskTracker) remain external for now and are surfaced in GlobalNav as external links. AppNavConfig.kind discriminates the two tiers.",
      "affects": ["contracts — AppNavConfig shape", "GlobalNav rendering logic", "LocalNav — external apps have no LocalNav"]
    },
    {
      "question": "What happens to 02_Platform/UI/react/src/pages/ when App.tsx is deleted?",
      "decision": "The entire pages/ tree (Tasks.tsx, WorkoutSessions.tsx) is deleted. WorkoutSessions.tsx content migrates to 03_Application/WorkoutTracker/src/ShellEntry.tsx. Tasks.tsx is dropped; TaskTracker surfaces as an external link.",
      "affects": ["migration_steps in deferrals", "WorkoutTracker pilot requirement"]
    },
    {
      "question": "What is the href source for the TaskTracker external link entry?",
      "decision": "import.meta.env.VITE_TASKS_URL. This variable must be set in .env (development) and .env.production. If the variable is absent or resolves to an empty string, registerApp() treats the href as invalid and omits the entry entirely — the same INVALID_NAV_CONFIG path as any other missing required field. The entry is not rendered as a disabled/broken link; it is simply not shown.",
      "affects": ["contracts.failure_modes — MISSING_EXTERNAL_HREF", "contracts.invariants", "registerApp() validation logic", "migration steps — .env files", "apps/index.ts stub"]
    },
    {
      "question": "Should WorkoutTracker's internal navigation use react-router-dom sub-routes or stay as a state machine?",
      "decision": "Convert to react-router-dom nested Routes under /workout/*. ShellEntry.tsx renders its own <Routes> block (no BrowserRouter — it inherits the shell's router context). LocalNav paths map directly to these sub-routes (e.g. /workout, /workout/performance, /workout/history). This is a constraint on the WorkoutTracker migration: ShellEntry.tsx must not instantiate a BrowserRouter; it must use only Routes, Route, NavLink, useNavigate, and useParams from the shell's inherited context.",
      "affects": ["contracts.consumes — ShellEntry contract spec", "contracts.invariants — no nested BrowserRouter", "migration step 7", "risks"]
    },
    {
      "question": "Does the 02_Platform/UI/react/ Vite project wrapper need to be retained for @platform-ui alias resolution?",
      "decision": "No. The @platform-ui alias resolves directly into 02_Platform/UI/react/src/. The react/ wrapper files (react/package.json, react/index.html, react/vite.config.ts, react/tsconfig*.json) are not needed for shell operation. They may be retained for standalone development of platform UI primitives but are not a shell dependency and are not referenced by the shell's vite.config.ts or tsconfig.json.",
      "affects": ["dependencies.internal_required — clarified scope", "vite.config.ts alias target", "migration steps — wrapper files are optional to delete"]
    }
  ],

  "contracts": {
    "consumes": [
      "AppNavConfig — navigation registration object declared for each app in src/apps/index.ts; NativeAppNavConfig carries a React.lazy component reference; ExternalAppNavConfig carries an href sourced from VITE_TASKS_URL",
      "WorkoutTracker ShellEntry — default-export React component at 03_Application/WorkoutTracker/src/ShellEntry.tsx; must render a nested <Routes> (no BrowserRouter) covering the sub-paths declared in its NativeAppNavConfig nav lists; must not instantiate its own router context"
    ],
    "provides": [
      "ShellLayout — the rendered desktop/tablet/mobile layout frame with BrowserRouter-aware routing",
      "GlobalNav — rendered level-1 navigation: Atlas launcher, native app NavLinks, external app <a> links (only when href is set); sorted by AppNavConfig.order",
      "LocalNav — rendered level-2 navigation for the active native app; external apps produce no LocalNav",
      "AppRegistry — runtime map of all registered AppNavConfigs; read by all nav components",
      "useShellNav() — hook exposing activeAppId and react-router-dom navigate to native application components"
    ],
    "invariants": [
      "Shell renders no domain-specific content; all content inside a native app's Route is application-owned",
      "Navigation items are rendered exclusively from AppNavConfig declarations; shell never hardcodes app names, routes, or hrefs",
      "Mobile bottom navigation never exceeds 5 items (Material Design constraint, definition §5 and §14)",
      "Level-1 navigation is always rendered for all registered apps regardless of kind",
      "Level-2 navigation (LocalNav) is only rendered when a native app is active; external apps produce no LocalNav",
      "A new application can be added by adding an entry in src/apps/index.ts without modifying any shell component source",
      "The shell exposes no persistent state to the backend; all state is in-memory and UI-local",
      "registerApp() is called exclusively from src/apps/index.ts before the React tree mounts",
      "AppNavConfig is the single authoritative navigation contract type; applications never define a local substitute",
      "AppNavConfig.order is the authoritative sort key for nav entry display order; registration order is not relied upon",
      "Native app source is imported only via React.lazy in src/apps/index.ts; no other shell file imports from 03_Application",
      "Each alias (e.g. '@workout', '@platform-ui') is declared in both vite.config.ts resolve.alias and tsconfig.json paths",
      "External app entries with an absent or empty VITE_TASKS_URL are omitted from the registry entirely; they are not rendered as disabled links",
      "No BrowserRouter exists inside any native application component; native apps inherit the shell's router context"
    ],
    "failure_modes": [
      "NO_APPS_REGISTERED — registry is empty at render time; shell renders an empty launcher state",
      "INVALID_NAV_CONFIG — AppNavConfig fails validation (missing required field, invalid kind, native config missing component, external config missing or empty href); shell skips that app and logs console.error; does not throw",
      "MISSING_EXTERNAL_HREF — VITE_TASKS_URL is absent or empty at build time; the ExternalAppNavConfig for TaskTracker fails href validation and is omitted from the registry; TaskTracker does not appear in GlobalNav or Launcher",
      "UNKNOWN_ROUTE — URL does not match any registered native basePath; shell renders the Launcher view (route '/')",
      "MOBILE_NAV_OVERFLOW — more than 5 items in mobilePrimaryNav; shell truncates to 5 and logs console.warn in development; silent in production",
      "OUTLET_RENDER_ERROR — native application component throws during render; ShellErrorBoundary catches it and renders ErrorCard; shell nav remains functional",
      "LAZY_LOAD_FAILURE — React.lazy import fails (alias misconfiguration, module not found); Suspense shows Skeleton fallback; ShellErrorBoundary catches and renders ErrorCard",
      "EXTERNAL_LINK_DEAD — an external app href is unreachable at click time; network-level failure outside the shell's failure domain; shell has already validated href is non-empty at registration"
    ]
  },

  "shared_views": {
    "consumes": [],
    "provides": [
      "AppNavConfig — navigation registration contract type (NativeAppNavConfig | ExternalAppNavConfig union); defined in types/nav.ts; consumed by src/apps/index.ts"
    ]
  },

  "interfaces": {
    "consumes": [
      "02_Platform/UI/react/src/components/ErrorCard.tsx — imported by ShellErrorBoundary as the error fallback; accessed via @platform-ui alias resolving into react/src/",
      "02_Platform/UI/react/src/components/Skeleton.tsx — imported as the React Suspense fallback during lazy load; accessed via @platform-ui alias",
      "02_Platform/UI/react/src/index.css — platform CSS tokens and primitive styles; imported by shell main.tsx via @platform-ui alias",
      "00_Blueprint/UI — design language tokens applied in shell.css",
      "react-router-dom v6 — BrowserRouter, Routes, Route, NavLink, useNavigate, useParams, useMatch"
    ],
    "provides": [
      "useShellNav(): { activeAppId: string | null; navigate: NavigateFunction } — hook for native application components; wraps react-router-dom useNavigate with activeAppId from ShellContext; throws if called outside ShellLayout",
      "AppNavConfig (type) — imported by src/apps/index.ts; two variants: NativeAppNavConfig (kind: 'native', component: LazyExoticComponent) and ExternalAppNavConfig (kind: 'external', href: string)",
      "NavItem (type) — imported by src/apps/index.ts for nav entry objects"
    ],
    "exposed_surfaces": [
      {
        "type": "typescript_export",
        "name": "NativeAppNavConfig",
        "purpose": "Navigation contract for apps loaded inside the shell outlet. Required: appId, label, basePath, order, kind='native', component (React.lazy), mobilePrimaryNav (max 5), desktopNav. Optional: secondaryMenu."
      },
      {
        "type": "typescript_export",
        "name": "ExternalAppNavConfig",
        "purpose": "Navigation contract for apps surfaced as external links. Required: appId, label, order, kind='external', href (non-empty string; sourced from import.meta.env.VITE_TASKS_URL for TaskTracker). Empty href treated as invalid at registration."
      },
      {
        "type": "typescript_export",
        "name": "AppNavConfig",
        "purpose": "Union type: NativeAppNavConfig | ExternalAppNavConfig. Used everywhere a config is accepted generically."
      },
      {
        "type": "typescript_export",
        "name": "NavItem",
        "purpose": "Single navigation entry (id, label, path, order) used in mobilePrimaryNav, desktopNav, secondaryMenu."
      },
      {
        "type": "react_component",
        "name": "ShellLayout",
        "purpose": "Root shell component; mounted once by main.tsx inside BrowserRouter; owns Routes (for native apps only), ShellContext, layout variant, and nav composition."
      },
      {
        "type": "typescript_export",
        "name": "useShellNav",
        "purpose": "Hook for native application components to read activeAppId and access navigate(); must be called inside the ShellLayout tree."
      }
    ]
  },

  "internal_flow": [
    {
      "step": 1,
      "name": "startup_registration",
      "description": "main.tsx imports src/apps/index.ts before rendering. For WorkoutTracker, apps/index.ts declares React.lazy(() => import('@workout/ShellEntry')) and calls registerApp() with a NativeAppNavConfig. For TaskTracker, apps/index.ts reads import.meta.env.VITE_TASKS_URL and calls registerApp() with an ExternalAppNavConfig. registerApp() validates each config by kind; an empty or absent VITE_TASKS_URL causes the TaskTracker entry to be skipped (INVALID_NAV_CONFIG path). The 5-item mobilePrimaryNav cap is enforced on native configs. AppRegistry is fully populated before the React tree mounts.",
      "inputs": ["NativeAppNavConfig and ExternalAppNavConfig objects declared in src/apps/index.ts", "import.meta.env.VITE_TASKS_URL from environment"],
      "outputs": ["populated AppRegistry (module-level Map keyed by appId); TaskTracker absent if VITE_TASKS_URL is unset"]
    },
    {
      "step": 2,
      "name": "react_tree_mount",
